  if (blacklist.some(v => tmpl.includes(v))) {
    for(var i=0; i<tmpl.length; i++){
      if(blacklist.includes(tmpl[i])){
        tmpl = tmpl.replace(tmpl[i], "");
      }
    }
  } 
